classdef plotPowerSpectrumTest < matlab.unittest.TestCase
%PLOTPOWERSPECTRUMTEST  Unit tests for plotPowerSpectrum.
%
%   Verifies amplitude/PSD scaling, peak detection, the FFT (Welch) and
%   Lomb-Scargle branches, gap handling, output struct shapes and options.
%   Figures are created on an off-screen axes and closed in teardown.
%
%   Run with:  results = runtests('plotPowerSpectrumTest')
%
%   Base MATLAB only.
%
%   ------------------------------------------------------------------
%   Toolbox : sigtools (tests)
%   Author  : Generated by Claude Opus 4.8 (Anthropic)
%   Date    : 2026-07-15  (build time-of-day not available in this environment)
%   ------------------------------------------------------------------

    properties
        fig
    end

    methods (TestMethodTeardown)
        function closeFigs(tc)
            if ~isempty(tc.fig) && all(isgraphics(tc.fig))
                close(tc.fig);
            end
            tc.fig = [];
        end
    end

    methods (Access = private)
        function ax = freshAxes(tc)
            tc.fig = figure('Visible','off');
            ax = axes('Parent', tc.fig);
        end
    end

    methods (Test)

    function amplitudeScalingFFT(tc)
        % A pure sinusoid at an on-bin frequency must peak at ~A.
        rng(201);
        fs = 200; t = (0:1/fs:40)'; A = 1.7; f0 = 5;
        x = A*sin(2*pi*f0*t);
        ax = tc.freshAxes();
        [pk, S] = timeSeriesPreparation.spectral.plotPowerSpectrum({fs, x, 's'}, 'Type','amplitude', ...
            'Window','rect', 'NPeaks',1, 'Axes',ax);
        tc.verifyEqual(S.method, 'fft');
        tc.verifyEqual(pk.frequency, f0, 'AbsTol', 0.2);
        tc.verifyEqual(pk.amplitude, A, 'RelTol', 0.05);
    end

    function psdParsevalApprox(tc)
        % One-sided PSD integrated over f ~ variance of the (detrended) signal.
        rng(202);
        fs = 100; t = (0:1/fs:60)';
        x = randn(numel(t),1);
        ax = tc.freshAxes();
        [~, S] = timeSeriesPreparation.spectral.plotPowerSpectrum({fs, x}, 'Type','psd', ...
            'Window','rect', 'Detrend','mean', 'Axes',ax);
        df = S.frequency(2) - S.frequency(1);
        integ = sum(S.power)*df;          % one-sided integral
        tc.verifyEqual(integ, var(x,1), 'RelTol', 0.15);
    end

    function lombBranchOnGaps(tc)
        % NaN gaps must switch the estimator to Lomb-Scargle.
        rng(203);
        fs = 50; t = (0:1/fs:40)';
        x = 1.2*sin(2*pi*3*t) + 0.3*randn(numel(t),1);
        x(500:650) = NaN;
        ax = tc.freshAxes();
        [pk, S] = timeSeriesPreparation.spectral.plotPowerSpectrum({t, x, 'gap'}, 'Type','amplitude', ...
            'NPeaks',1, 'Axes',ax);
        tc.verifyEqual(S.method, 'lomb-scargle');
        tc.verifyEqual(pk.frequency, 3, 'AbsTol', 0.1);
    end

    function unevenSamplingLomb(tc)
        rng(204);
        t = sort(30*rand(1500,1));
        x = 2.0*sin(2*pi*4*t) + 0.4*randn(size(t));
        ax = tc.freshAxes();
        [pk, S] = timeSeriesPreparation.spectral.plotPowerSpectrum({t, x}, 'Type','amplitude', ...
            'NPeaks',1, 'MaxFreq',10, 'Axes',ax);
        tc.verifyEqual(S.method, 'lomb-scargle');
        tc.verifyEqual(pk.frequency, 4, 'AbsTol', 0.1);
        tc.verifyEqual(pk.amplitude, 2.0, 'RelTol', 0.15);
    end

    function customFrequenciesForceLomb(tc)
        rng(205);
        fs = 20; t = (0:1/fs:50)';
        x = sin(2*pi*2*t) + 0.3*randn(numel(t),1);
        fgrid = linspace(0.1, 8, 300);
        ax = tc.freshAxes();
        [~, S] = timeSeriesPreparation.spectral.plotPowerSpectrum({fs, x}, 'Frequencies', fgrid, 'Axes', ax);
        tc.verifyEqual(S.method, 'lomb-scargle');
        tc.verifyEqual(numel(S.frequency), numel(fgrid));
    end

    function welchReducesVariance(tc)
        % More Welch averages -> smaller noise-floor scatter (lower std of log PSD).
        rng(206);
        fs = 100; t = (0:1/fs:120)';
        x = randn(numel(t),1);
        ax1 = tc.freshAxes();
        [~, S1] = timeSeriesPreparation.spectral.plotPowerSpectrum({fs, x}, 'NAvg',1,  'Axes',ax1); close(tc.fig);
        ax2 = tc.freshAxes();
        [~, S8] = timeSeriesPreparation.spectral.plotPowerSpectrum({fs, x}, 'NAvg',8, 'Overlap',0.5, 'Axes',ax2);
        s1 = std(log(S1.power(S1.frequency>1)));
        s8 = std(log(S8.power(S8.frequency>1)));
        tc.verifyLessThan(s8, s1);
        tc.verifyEqual(S8.nseg, 8);
    end

    function multiSeriesOutputs(tc)
        rng(207);
        fs = 100; t = (0:1/fs:20)';
        x1 = sin(2*pi*5*t);
        t2 = sort(20*rand(800,1)); x2 = sin(2*pi*7*t2);
        ax = tc.freshAxes();
        [pk, S, H] = timeSeriesPreparation.spectral.plotPowerSpectrum({t, x1, 'A'}, {t2, x2, 'B'}, ...
            'NPeaks',1, 'Axes',ax);
        tc.verifySize(S, [1 2]);
        tc.verifySize(pk, [1 2]);
        tc.verifyEqual(S(1).method, 'fft');
        tc.verifyEqual(S(2).method, 'lomb-scargle');
        tc.verifyNumElements(H.lines, 2);
    end

    function peaksSubBinRefinement(tc)
        % Off-bin frequency: parabolic refinement should beat the raw bin.
        rng(208);
        fs = 1000; t = (0:1/fs:5)';
        f0 = 123.37; x = 2*sin(2*pi*f0*t);
        ax = tc.freshAxes();
        pk = timeSeriesPreparation.spectral.plotPowerSpectrum({fs, x}, 'Type','amplitude', ...
            'Window','flattop', 'NPeaks',1, 'Axes',ax);
        tc.verifyEqual(pk.frequency, f0, 'AbsTol', 0.5);
        tc.verifyEqual(pk.amplitude, 2.0, 'RelTol', 0.03);
    end

    function fapLevelsPopulated(tc)
        rng(209);
        t = sort(100*rand(600,1));
        x = 0.5*sin(2*pi*t/13) + randn(size(t));
        ax = tc.freshAxes();
        [~, S] = timeSeriesPreparation.spectral.plotPowerSpectrum({t, x}, 'FAP',[0.05 0.01], ...
            'MaxFreq',0.5, 'Axes',ax);
        tc.verifyNotEmpty(S.fapLevels);
        tc.verifyNumElements(S.fapLevels.fap, 2);
        tc.verifyEqual(S.fapLevels.method, 'analytic');
    end

    function datetimeTimeVector(tc)
        rng(210);
        fs = 10; n = 600;
        t0 = datetime(2026,1,1);
        t  = t0 + seconds((0:n-1)'/fs);
        x  = sin(2*pi*1.5*seconds(t-t0)) + 0.2*randn(n,1);
        ax = tc.freshAxes();
        [pk, S] = timeSeriesPreparation.spectral.plotPowerSpectrum({t, x}, 'Type','amplitude', ...
            'NPeaks',1, 'Axes',ax);
        tc.verifyEqual(S.method, 'fft');
        tc.verifyEqual(pk.frequency, 1.5, 'AbsTol', 0.1);
    end

    function badInputErrors(tc)
        tc.verifyError(@() timeSeriesPreparation.spectral.plotPowerSpectrum(), ?MException);
    end

    end
end
